  // Initialize the singleton
  init() {
    this.initializeCommentsSection();
    this.initializeSubscriptionState();
    this.bindEventListeners();
    this.setupMorePostOptionsDropdown();
  }

  // 1. Like Post Functionality
  async likePost(btn) {
    if (!this.postId) {
      console.error("Post ID not found");
      return;
    }

    try {
      const result = await window.frappeClient.post("Cafe Social Like", {
        post: this.postId,
      });

      const likedByMe = result.data.liked_by_me;
      const likeCount = result.data.like_count;

      this.updateLikeButton(btn, likedByMe);
      this.updateLikeCount(likeCount);

      return result;
    } catch (error) {
      console.error("Error liking post:", error);
      toast.error(error.message || "Failed to like post");
      throw error;
    }
  }

  updateLikeButton(btn, likedByMe) {
    const svgPath = btn.querySelector("path");
    if (svgPath) {
      if (likedByMe) {
        svgPath.setAttribute("d", this.svgPaths.heart.filled);
        svgPath.style.fill = "#ef4444";
      } else {
        svgPath.setAttribute("d", this.svgPaths.heart.outline);
        svgPath.style.fill = "#525252";
      }
    }
  }

  updateLikeCount(count) {
    const likeCountElement = document.getElementById("post-likes-count");
    if (likeCountElement) {
      likeCountElement.textContent = count;
    }
  }

  // 2. Bookmark Post Functionality
  async bookmarkPost(btn) {
    if (!this.postId) {
      console.error("Post ID not found");
      return;
    }

    try {
      const result = await window.frappeClient.post("Cafe Post Bookmark", {
        post: this.postId,
      });

      const isBookmarked = result.data.bookmarked_by_me;

      this.updateBookmarkButton(btn, isBookmarked);

      return result;
    } catch (error) {
      console.error("Error bookmarking post:", error);
      toast.error("An error occurred while bookmarking");
      throw error;
    }
  }

  updateBookmarkButton(btn, isBookmarked) {
    const pathElement = btn.querySelector("path");
    if (pathElement) {
      if (isBookmarked) {
        pathElement.setAttribute("d", this.svgPaths.bookmark.filled);
        pathElement.style.fill = "#000000";
      } else {
        pathElement.setAttribute("d", this.svgPaths.bookmark.outline);
        pathElement.style.fill = "#525252";
      }
    }
  }

  // 3. Share Post Functionality
  async sharePost() {
    if (navigator.share) {
      try {
        await navigator.share({
          title: document.title,
          text: "Check out this post!",
          url: window.location.href,
        });
      } catch (error) {
        if (error.name !== "AbortError") {
          console.error("Error sharing post:", error);
        }
      }
    } else {
      this.copyPostUrl();
    }
  }

  // 4. Copy Post URL Functionality
  async copyPostUrl() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      toast.success("Post link copied");
    } catch (error) {
      console.error("Error copying URL:", error);
      toast.error("Failed to copy link");
    }
  }

  // 5. Add Comment Functionality
  async addComment(content) {
    if (!this.postId || !content?.trim()) {
      return;
    }

    try {
      const result = await window.frappeClient.post("Cafe Post Comment", {
        content: content.trim(),
        post: this.postId,
      });

      // Clear input and reload page to show new comment
      const commentInput = document.getElementById("comment-input");
      if (commentInput) {
        commentInput.value = "";
      }

      window.location.reload();
      return result;
    } catch (error) {
      console.error("Error submitting comment:", error);
      toast.error(error.message || "Failed to submit comment");
      throw error;
    }
  }

  // 6. Like Comment Functionality
  async likeComment(commentId, btn) {
    // Prevent duplicate requests for the same comment
    if (this.likingComments.has(commentId)) {
      return;
    }

    this.likingComments.add(commentId);

    try {
      const result = await frappeClient.post("Cafe Social Like", {
        comment: commentId,
      });

      const likedByMe = result.data.liked_by_me;
      const likeCount = result.data.like_count;

      this.updateCommentLikeButton(btn, likedByMe);
      this.updateCommentLikeCount(btn, likeCount);

      return result;
    } catch (error) {
      console.error("Error liking comment:", error);
      throw error;
    } finally {
      this.likingComments.delete(commentId);
    }
  }

  updateCommentLikeButton(btn, likedByMe) {
    const iconContainer = btn.querySelector(".comment-like-icon");
    if (iconContainer) {
      const svgPath = iconContainer.querySelector("path");
      if (svgPath) {
        if (likedByMe) {
          svgPath.setAttribute("d", this.svgPaths.thumbsUp.filled);
        } else {
          svgPath.setAttribute("d", this.svgPaths.thumbsUp.outline);
        }
      }
    }
  }

  updateCommentLikeCount(btn, count) {
    const countElement = btn.querySelector(".comment-like-count");
    if (countElement) {
      countElement.textContent = count;
    }
  }

  // 7. Load More Comments Functionality
  async loadMoreComments(btn) {
    if (this.isLoadingComments || !this.hasMoreComments) return;

    const originalText = btn.innerHTML;
    this.isLoadingComments = true;
    btn.disabled = true;
    this.setButtonText(btn, "Loading...");

    try {
      // Use the new API method to get comments with full data
      const comments = await this.fetchCommentsViaMethod(
        this.commentsOffset,
        this.commentsLimit,
      );

      if (comments.length === 0) {
        this.hasMoreComments = false;
        btn.style.display = "none";
        return;
      }

      const commentsList = document.getElementById("comments-list");
      const commentsContainer =
        commentsList.querySelector("div") || commentsList;

      // Filter out already loaded comments
      const newComments = comments.filter(
        (comment) => !this.loadedCommentIds.has(comment.name),
      );

      newComments.forEach((comment) => {
        const result = this.renderComment(comment);
        let commentElement;

        if (typeof result === "string") {
          commentsContainer.insertAdjacentHTML("beforeend", result);
          // Get the newly added element
          const newElements = commentsContainer.querySelectorAll(
            `[comment-id="${comment.name}"]`,
          );
          commentElement = newElements[newElements.length - 1];
        } else {
          commentsContainer.appendChild(result);
          commentElement = result;
        }

        // Rebind event listeners for the new comment
        this.rebindCommentEventListeners(commentElement);
        this.loadedCommentIds.add(comment.name);
      });

      this.commentsOffset += newComments.length;

      // Update URL with comment cursor
      const url = new URL(window.location.href);
      url.searchParams.set("commentsCursor", this.commentsOffset);
      window.history.pushState({}, "", url);

      if (newComments.length < this.commentsLimit) {
        this.hasMoreComments = false;
        btn.style.display = "none";
      }
    } catch (error) {
      console.error("Failed to load more comments:", error);
      this.setButtonText(btn, "Error - Try Again");
      btn.disabled = false;
      this.isLoadingComments = false;
      return;
    }

    btn.innerHTML = originalText;
    btn.disabled = false;
    this.isLoadingComments = false;
  }

  async fetchComments(start, limit) {
    const result = await window.frappeClient.getDocList("Cafe Post Comment", {
      fields: [
        "name",
        "content",
        "post",
        "comment",
        "owner",
        "creation",
        "modified",
      ],
      filters: [["post", "=", this.postId]],
      start: start,
      limit: limit,
    });

    // Frappe API returns { data: [...] } structure
    return result?.data || result || [];
  }

  // Fetch comments using the specific Frappe method
  async fetchCommentsViaMethod(start = 0, limit = 10) {
    if (!this.postId) {
      throw new Error("Post ID is required to fetch comments");
    }

    try {
      const result = await window.frappeClient.call(
        "cafe.cafe.doctype.cafe_post.cafe_post.get_post_comments",
        {
          post_id: this.postId,
          start: start.toString(),
          limit: limit.toString(),
        },
        { useQuery: true },
      );

      // The response structure is { message: [...] }
      return result?.message || [];
    } catch (error) {
      console.error("Error fetching comments via method:", error);
      throw error;
    }
  }

  renderComment(comment) {
    const commentDate = this.formatRelativeTime(comment.creation);
    const userName = comment.owner || "Anonymous";

    const existingComment = document.querySelector("[comment-id]");
    if (existingComment) {
      return this.cloneCommentStructure(
        existingComment,
        comment,
        commentDate,
        userName,
      );
    }

    return this.buildCommentHTML(comment, commentDate, userName);
  }

  cloneCommentStructure(template, comment, date, userName) {
    const clone = template.cloneNode(true);

    clone.setAttribute("comment-id", comment.name);
    clone.setAttribute("data-block-uid", this.generateBlockUid());

    // Update comment data
    const userNameEls = clone.querySelectorAll(".comment-user-name");
    userNameEls.forEach(
      (el) => (el.textContent = comment.full_name || userName),
    );

    const userLinks = clone.querySelectorAll('a[href*="/profile/"]');
    userLinks.forEach((link) => {
      link.href =
        comment.author_url || `/cafe/profile/${userName.toLowerCase()}`;
    });

    const dateEls = clone.querySelectorAll(".comment-creation-date");
    dateEls.forEach((el) => (el.textContent = comment.time_ago || date));

    const contentEls = clone.querySelectorAll(".comment-content");
    contentEls.forEach((el) => (el.textContent = comment.content));

    // Update like button state and count
    const likeBtn = clone.querySelector(
      "button[comment-id]:has(.comment-like-icon)",
    );
    if (likeBtn) {
      likeBtn.setAttribute("comment-id", comment.name);
      this.updateCommentLikeButton(likeBtn, comment.liked_by_me || false);
      this.updateCommentLikeCount(likeBtn, comment.likes || 0);

      // Re-bind click event for like button
      likeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.likeComment(comment.name, likeBtn);
      });
    }

    // Update delete button
    const deleteBtn = clone.querySelector(".delete-btn");
    if (deleteBtn) {
      deleteBtn.setAttribute("comment-id", comment.name);
      deleteBtn.setAttribute("data-block-uid", this.generateBlockUid());
      deleteBtn.addEventListener("click", () => {
        this.deleteComment(comment.name, deleteBtn);
      });
    }

    // Update reply button
    const replyBtn = clone.querySelector(".comment-reply-btn");
    if (replyBtn) {
      const replyButtonContainer = replyBtn.closest("button[comment-id]");
      if (replyButtonContainer) {
        replyButtonContainer.setAttribute("comment-id", comment.name);
      }
    }

    return clone;
  }

  buildCommentHTML(comment, date, userName) {
    return `
<section comment-id="${this.escapeHtml(comment.name)}" data-block-uid="${this.generateBlockUid()}">
    <a href="${comment.author_url || `/cafe/profile/${userName.toLowerCase()}`}">
        <div>
            <img src="${comment.user_image || "/files/stock-image.jpg"}" alt="${this.escapeHtml(comment.full_name || userName)}">
        </div>
    </a>
    <section>
        <section>
            <a href="${comment.author_url || `/cafe/profile/${userName.toLowerCase()}`}">
                <section>
                    <div class="comment-user-name">${this.escapeHtml(comment.full_name || userName)}</div>
                </section>
                <section>
                    <div class="comment-creation-date">${comment.time_ago || date}</div>
                </section>
            </a>
            <button class="delete-btn" comment-id="${this.escapeHtml(comment.name)}" style="display: none;">
                <svg viewBox="0 0 13 15" xmlns="http://www.w3.org/2000/svg">
                    <path d="M7.22949 0C8.05781 0.000119744 8.72949 0.671652 8.72949 1.5V1.72949H11.3232V1.73828H12.5L12.6006 1.74805C12.8285 1.79461 13 1.9966 13 2.23828C12.9998 2.47978 12.8284 2.68202 12.6006 2.72852L12.5 2.73828H11.3232V12.0293C11.3232 13.41 10.2039 14.5293 8.82324 14.5293H4.17578C2.79522 14.5291 1.67579 13.4099 1.67578 12.0293V2.73828H0.5C0.22402 2.73828 0.000263701 2.5142 0 2.23828C0 1.96214 0.223858 1.73828 0.5 1.73828H1.67578V1.72949H4.27051V1.5C4.27051 0.67158 4.94208 0 5.77051 0H7.22949ZM2.67578 2.73828V12.0293C2.67579 12.8576 3.34751 13.5291 4.17578 13.5293H8.82324C9.65163 13.5293 10.3232 12.8577 10.3232 12.0293V2.73828H2.67578ZM4.98633 5.07812C5.26241 5.07812 5.48623 5.30206 5.48633 5.57812V10.5781C5.48633 10.8543 5.26247 11.0781 4.98633 11.0781C4.71019 11.0781 4.48633 10.8543 4.48633 10.5781V5.57812C4.48642 5.30206 4.71025 5.07812 4.98633 5.07812ZM8.01367 5.07812C8.28975 5.07812 8.51358 5.30206 8.51367 5.57812V10.5781C8.51367 10.8543 8.28981 11.0781 8.01367 11.0781C7.73753 11.0781 7.51367 10.8543 7.51367 10.5781V5.57812C7.51377 5.30206 7.73759 5.07812 8.01367 5.07812ZM5.77051 1C5.49437 1 5.27051 1.22386 5.27051 1.5V1.72949H7.72949V1.5C7.72949 1.22394 7.50553 1.00012 7.22949 1H5.77051Z" fill="red"></path>
                </svg>
            </button>
        </section>
        <section>
            <div class="comment-content">${this.escapeHtml(comment.content)}</div>
        </section>
        <section>
            <button comment-id="${this.escapeHtml(comment.name)}">
                <div class="comment-like-icon">
                    <svg fill="none" height="15" viewBox="0 0 15 15" width="15" xmlns="http://www.w3.org/2000/svg">
                        <g clip-path="url(#clip0_296_2879)">
                            <path d="${comment.liked_by_me ? this.svgPaths.thumbsUp.filled : this.svgPaths.thumbsUp.outline}" fill="#525252"></path>
                        </g>
                        <defs>
                            <clipPath id="clip0_296_2879">
                                <rect fill="white" height="15" width="15"></rect>
                            </clipPath>
                        </defs>
                    </svg>
                </div>
                <span class="comment-like-count">${comment.likes || 0}</span>
            </button>
            <button comment-id="${this.escapeHtml(comment.name)}">
                <span class="comment-reply-btn">Reply</span>
            </button>
        </section>
    </section>
</section>`;
  }

  // 8. Delete Comment Functionality
  async deleteComment(commentId, btn) {
    return new Promise((resolve) => {
      window.dialog({
        title: "Delete Comment",
        message: "Are you sure you want to delete this comment?",
        size: "sm",
        actions: [
          {
            label: "Delete",
            theme: "red",
            variant: "solid",
            onClick: async (close) => {
              try {
                await window.frappeClient.delete(
                  "Cafe Post Comment",
                  commentId,
                );
                window.location.reload();
                resolve();
              } catch (error) {
                console.error("Error deleting comment:", error);
                toast.error("Failed to delete comment");
                throw error;
              }
            },
          },
          {
            label: "Cancel",
            variant: "outline",
            onClick: (close) => close(),
          },
        ],
      });
    });
  }

  // 9. Subscribe to Author Functionality
  async toggleSubscribe(publication) {
    // Set loading state
    this.subscriptionState.isLoading = true;
    this.subscriptionState.error = null;
    this.updateSubscribeButtons();

    try {
      // Check if author is a publisher and determine subscription target
      let subscriptionTarget;
      if (this.author?.is_publisher === 1) {
        // Subscribe to publication if author is a publisher
        subscriptionTarget = this.author?.handle || publication;
      } else {
        // Subscribe to user if author is not a publisher
        subscriptionTarget = this.author?.name || publication;
      }

      // Use different parameter names based on subscription type
      const subscriptionParams =
        this.author?.is_publisher === 1
          ? { publisher: subscriptionTarget }
          : { user: subscriptionTarget };

      const result = await window.frappeClient.post(
        "Cafe Subscription",
        subscriptionParams,
      );

      const isSubscribed = result.data.subscribed_by_me;
      const subscriberCount =
        result.data.subscriber_count || this.subscriptionState.subscriberCount;

      // Update subscription state
      this.subscriptionState.isSubscribed = isSubscribed;
      this.subscriptionState.isLoading = false;
      this.subscriptionState.error = null;
      this.subscriptionState.subscriberCount = subscriberCount;

      this.updateSubscribeButtons();

      const subscriptionType =
        this.author?.is_publisher === 1 ? "publication" : "user";
      toast.success(
        isSubscribed
          ? `Subscribed to ${subscriptionType}`
          : `Unsubscribed from ${subscriptionType}`,
      );

      return result;
    } catch (error) {
      console.error("Error toggling subscription:", error);

      // Update error state
      this.subscriptionState.isLoading = false;
      this.subscriptionState.error = error.message;

      this.updateSubscribeButtons();

      toast.error(error.message || "Failed to update subscription");
      throw error;
    }
  }

  initializeSubscriptionState() {
    // Initialize subscription state from author data
    this.subscriptionState = {
      isSubscribed: this.author?.is_subscribed || false,
      isLoading: false,
      error: null,
      subscriberCount: this.author?.subscriber_count || 0,
    };

    this.updateSubscribeButtons();
  }

  updateSubscribeButtons() {
    const state = this.subscriptionState;

    document.querySelectorAll(".subscribe-btn").forEach((btn) => {
      const textContent = btn.querySelector(".__text_block__");

      if (textContent) {
        if (state.isLoading) {
          textContent.textContent = "Loading...";
          btn.disabled = true;
          btn.style.opacity = "0.6";
          btn.style.cursor = "not-allowed";
        } else {
          textContent.textContent = state.isSubscribed
            ? "Subscribed"
            : "Subscribe";
          btn.disabled = false;
          btn.style.opacity = "1";
          btn.style.cursor = "pointer";
        }
      }

      if (state.error && !state.isLoading) {
        btn.style.borderColor = "#ef4444";
        btn.style.borderWidth = "2px";
      } else {
        btn.style.borderColor = "";
        btn.style.borderWidth = "";
      }
    });
  }

