  async deletePost() {
    window.dialog({
      title: "Delete Post",
      message:
        "Are you sure you want to delete this post? This action cannot be undone.",
      size: "sm",
      actions: [
        {
          label: "Delete",
          theme: "red",
          variant: "solid",
          onClick: async (close) => {
            try {
              await window.frappeClient.delete("Cafe Post", this.postId);
              window.location.href = "/cafe";
            } catch (error) {
              console.error("Error deleting post:", error);
              toast.error(error.message || "Failed to delete post");
            }
          },
        },
        {
          label: "Cancel",
          variant: "outline",
          onClick: (_close) => _close(),
        },
      ],
    });
  }

  // 11. Visit Author Page Functionality
  visitAuthorPage(authorName) {
    if (authorName) {
      window.location.href = `/cafe/profile/${authorName.toLowerCase()}`;
    } else if (this.author?.name) {
      window.location.href = `/cafe/profile/${this.author.name.toLowerCase()}`;
    }
  }

  // Initialize comments section
  initializeCommentsSection() {
    const commentsList = document.getElementById("comments-list");
    const loadMoreBtn = this.findLoadMoreButton();

    if (!commentsList || !loadMoreBtn) {
      console.warn("Load more comments: Required elements not found");
      return;
    }

    const existingComments =
      commentsList.querySelectorAll(".comment-container");
    existingComments.forEach((comment) => {
      const commentId = comment.getAttribute("comment-id");
      if (commentId) this.loadedCommentIds.add(commentId);
    });

    this.commentsOffset = existingComments.length;

    if (existingComments.length < this.commentsLimit) {
      loadMoreBtn.style.display = "none";
    }

    loadMoreBtn.addEventListener("click", (e) => {
      this.loadMoreComments(e.currentTarget);
    });
  }

  findLoadMoreButton() {
    // First try to find by ID
    let btn = document.getElementById("load-more-btn");
    if (btn) return btn;

    // Then try to find by text content (case-insensitive)
    const buttons = document.querySelectorAll("button");
    for (const button of buttons) {
      const text = button.textContent?.toLowerCase() || "";
      if (text.includes("load more") || text.includes("load more comments")) {
        return button;
      }
    }

    // Finally, try to find by common classes or attributes
    return document.querySelector(
      '[class*="load-more"], [data-action="load-more"]',
    );
  }

  // Bind event listeners
  bindEventListeners() {
    // Prevent duplicate event listeners
    if (this.eventListenersAttached) {
      return;
    }

    // Like post buttons
    document.querySelectorAll('[class*="like"]').forEach((btn) => {
      if (btn.getAttribute("post-id") || btn.closest('[class*="post"]')) {
        btn.addEventListener("click", () => this.likePost(btn));
      }
    });

    // Bookmark buttons
    document.querySelectorAll('[class*="bookmark"]').forEach((btn) => {
      if (btn.getAttribute("post-id") || btn.closest('[class*="post"]')) {
        btn.addEventListener("click", () => this.bookmarkPost(btn));
      }
    });

    // Share buttons
    document.querySelectorAll('[class*="share"]').forEach((btn) => {
      btn.addEventListener("click", () => this.sharePost());
    });

    // Copy URL buttons
    document.querySelectorAll('[class*="copy"]').forEach((btn) => {
      btn.addEventListener("click", () => this.copyPostUrl());
    });

    // Comment submit
    const submitBtn = document.getElementById("comment-submit-btn");
    if (submitBtn) {
      submitBtn.addEventListener("click", () => {
        const commentInput = document.getElementById("comment-input");
        if (commentInput) {
          this.addComment(commentInput.value);
        }
      });
    }

    // Comment input enter key
    const commentInput = document.getElementById("comment-input");
    if (commentInput) {
      commentInput.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          this.addComment(commentInput.value);
        }
      });
    }

    // Comment like buttons - target buttons with comment-id attribute that contain like icons
    document.querySelectorAll("button[comment-id]").forEach((likeBtn) => {
      // Check if this button has a like icon (thumbs up SVG)
      const hasLikeIcon = likeBtn.querySelector(".comment-like-icon");
      const isDeleteBtn =
        likeBtn.classList.contains("delete-btn") ||
        likeBtn.querySelector('path[fill="red"]');
      const isReplyBtn = likeBtn.querySelector(".comment-reply-btn");

      // Only bind like functionality to actual like buttons
      if (hasLikeIcon && !isDeleteBtn && !isReplyBtn) {
        likeBtn.addEventListener("click", (e) => {
          e.stopPropagation(); // Prevent event bubbling to parent elements
          const commentId = likeBtn.getAttribute("comment-id");
          this.likeComment(commentId, likeBtn);
        });
      }
    });

    // Delete comment buttons
    document.querySelectorAll("button[comment-id]").forEach((deleteBtn) => {
      const isDeleteBtn =
        deleteBtn.classList.contains("delete-btn") ||
        deleteBtn.querySelector('path[fill="red"]');

      if (isDeleteBtn) {
        deleteBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          const commentId = deleteBtn.getAttribute("comment-id");
          this.deleteComment(commentId, deleteBtn);
        });
      }
    });

    // Subscribe buttons
    document.querySelectorAll(".subscribe-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        this.toggleSubscribe(this.author?.handle);
      });
    });

    // Author profile links
    document
      .querySelectorAll('[class*="author"], [class*="profile"]')
      .forEach((btn) => {
        btn.addEventListener("click", () => {
          const authorName = this.author?.name;
          this.visitAuthorPage(authorName);
        });
      });

    // Mark event listeners as attached
    this.eventListenersAttached = true;
  }

  // Rebind event listeners for dynamically loaded comments
  rebindCommentEventListeners(commentElement) {
    if (!commentElement) return;

    // Find like button within this comment element
    const likeBtn = commentElement.querySelector(
      "button[comment-id]:has(.comment-like-icon)",
    );
    if (likeBtn) {
      const commentId = likeBtn.getAttribute("comment-id");
      likeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.likeComment(commentId, likeBtn);
      });
    }

    // Find delete button within this comment element
    const deleteBtn = commentElement.querySelector(".delete-btn");
    if (deleteBtn) {
      const commentId = deleteBtn.getAttribute("comment-id");
      deleteBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.deleteComment(commentId, deleteBtn);
      });
    }
  }

  // Utility functions
  setButtonText(btn, text) {
    const textEl = btn.querySelector('[class*="__text_block__"]') || btn;
    if (textEl.tagName === "BUTTON") {
      btn.textContent = text;
    } else {
      textEl.textContent = text;
    }
  }

  formatRelativeTime(dateString) {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffSecs = Math.floor(diffMs / 1000);
    const diffMins = Math.floor(diffSecs / 60);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffSecs < 60) return "Just now";
    if (diffMins < 60)
      return `${diffMins} minute${diffMins !== 1 ? "s" : ""} ago`;
    if (diffHours < 24)
      return `${diffHours} hour${diffHours !== 1 ? "s" : ""} ago`;
    if (diffDays < 30) return `${diffDays} day${diffDays !== 1 ? "s" : ""} ago`;
    if (diffDays < 365)
      return `${Math.floor(diffDays / 30)} month${Math.floor(diffDays / 30) !== 1 ? "s" : ""} ago`;
    return `${Math.floor(diffDays / 365)} year${Math.floor(diffDays / 365) !== 1 ? "s" : ""} ago`;
  }

  generateBlockUid() {
    return (
      Math.random().toString(36).substring(2, 8) +
      "-" +
      Math.floor(Math.random() * 10)
    );
  }

  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
}

